def seed_vat_rates(apps, schema_editor):
    """Every organization starts with the usual Tunisian rates, its finance settings' rate and every rate its
    products already have (D-283), so the product form can still show each product's rate."""
    Organization = apps.get_model("core", "Organization")
    Product = apps.get_model("catalog", "Product")
    VatRate = apps.get_model("catalog", "VatRate")
    FinanceSettings = apps.get_model("sales", "FinanceSettings")
    for organization in Organization.objects.all():
        rates = set(DEFAULT_RATES)
        rates |= set(
            Product.objects.filter(organization=organization, vat_rate__isnull=False).values_list("vat_rate", flat=True)
        )
        rates |= set(FinanceSettings.objects.filter(organization=organization).values_list("vat_rate", flat=True))
        VatRate.objects.bulk_create(
            [VatRate(organization=organization, rate=rate) for rate in sorted(rates)], ignore_conflicts=True
        )


